import{_ as a,o,c as e,am as r}from"./chunks/framework._FJXuPhs.js";const S=JSON.parse('{"title":"NoSQL  基础概念","description":"","frontmatter":{"title":"NoSQL  基础概念","excerpt":"NoSQL_基础概念","date":"2023-11-19 10:51:08","updated":"2023-11-19 10:51:08"},"headers":[],"relativePath":"数据库/基础知识/NoSQL  基础概念.md","filePath":"数据库/基础知识/NoSQL  基础概念.md","lastUpdated":null}'),d={name:"数据库/基础知识/NoSQL  基础概念.md"};function n(s,t,l,i,h,p){return o(),e("div",null,[...t[0]||(t[0]=[r('<h3 id="_1、nosql-是什么" tabindex="-1">1、NoSQL 是什么 <a class="header-anchor" href="#_1、nosql-是什么" aria-label="Permalink to &quot;1、NoSQL 是什么&quot;">​</a></h3><p>NoSQL（Not Only SQL 的缩写）泛指非关系型的数据库，主要针对的是键值、文档以及图形类型数据存储。并且，NoSQL 数据库天生支持分布式，数据冗余和数据分片等特性，旨在提供可扩展的高可用高性能数据存储解决方案。</p><p>NoSQL 数据库代表：HBase、Cassandra、MongoDB、Redis。</p><h4 id="sql-和-nosql-有什么区别" tabindex="-1">SQL 和 NoSQL 有什么区别？ <a class="header-anchor" href="#sql-和-nosql-有什么区别" aria-label="Permalink to &quot;SQL 和 NoSQL 有什么区别？&quot;">​</a></h4><table tabindex="0"><thead><tr><th></th><th>SQL 数据库</th><th>NoSQL 数据库</th></tr></thead><tbody><tr><td>数据存储模型</td><td>结构化存储，具有固定行和列的表格</td><td>非结构化存储。文档：JSON 文档，键值：键值对，宽列：包含行和动态列的表，图：节点和边</td></tr><tr><td>发展历程</td><td>开发于 1970 年代，重点是减少数据重复</td><td>开发于 2000 年代后期，重点是提升可扩展性，减少大规模数据的存储成本</td></tr><tr><td>例子</td><td>Oracle、MySQL、Microsoft SQL Server、PostgreSQL</td><td>文档：MongoDB、CouchDB，键值：Redis、DynamoDB，宽列：Cassandra、 HBase，图表：Neo4j、 Amazon Neptune、Giraph</td></tr><tr><td>ACID 属性</td><td>提供原子性、一致性、隔离性和持久性 (ACID) 属性</td><td>通常不支持 ACID 事务，为了可扩展、高性能进行了权衡，少部分支持比如 MongoDB 。不过，MongoDB 对 ACID 事务 的支持和 MySQL 还是有所区别的。</td></tr><tr><td>性能</td><td>性能通常取决于磁盘子系统。要获得最佳性能，通常需要优化查询、索引和表结构。</td><td>性能通常由底层硬件集群大小、网络延迟以及调用应用程序来决定。</td></tr><tr><td>扩展</td><td>垂直（使用性能更强大的服务器进行扩展）、读写分离、分库分表</td><td>横向（增加服务器的方式横向扩展，通常是基于分片机制）</td></tr><tr><td>用途</td><td>普通企业级的项目的数据存储</td><td>用途广泛比如图数据库支持分析和遍历连接数据之间的关系、键值数据库可以处理大量数据扩展和极高的状态变化</td></tr><tr><td>查询语法</td><td>结构化查询语言 (SQL)</td><td>数据访问语法可能因数据库而异</td></tr></tbody></table><h4 id="nosql-数据库有哪些类型" tabindex="-1">NoSQL 数据库有哪些类型？ <a class="header-anchor" href="#nosql-数据库有哪些类型" aria-label="Permalink to &quot;NoSQL 数据库有哪些类型？&quot;">​</a></h4><p>NoSQL 数据库主要可以分为下面四种类型：</p><ul><li><strong>键值</strong>：键值数据库是一种较简单的数据库，其中每个项目都包含键和值。这是极为灵活的 NoSQL 数据库类型，因为应用可以完全控制 value 字段中存储的内容，没有任何限制。Redis 和 DynanoDB 是两款非常流行的键值数据库。</li><li><strong>文档</strong>：文档数据库中的数据被存储在类似于 JSON（JavaScript 对象表示法）对象的文档中，非常清晰直观。每个文档包含成对的字段和值。这些值通常可以是各种类型，包括字符串、数字、布尔值、数组或对象等，并且它们的结构通常与开发者在代码中使用的对象保持一致。MongoDB 就是一款非常流行的文档数据库。</li><li><strong>图形</strong>：图形数据库旨在轻松构建和运行与高度连接的数据集一起使用的应用程序。图形数据库的典型使用案例包括社交网络、推荐引擎、欺诈检测和知识图形。Neo4j 和 Giraph 是两款非常流行的图形数据库。</li><li><strong>宽列</strong>：宽列存储数据库非常适合需要存储大量的数据。Cassandra 和 HBase 是两款非常流行的宽列存储数据库。</li></ul><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20231119123254.png" alt="image.png"></p><hr><p>参考</p><ul><li><a href="https://javaguide.cn/database/nosql.html" target="_blank" rel="noreferrer">https://javaguide.cn/database/nosql.html</a></li><li><a href="https://www.ibm.com/cn-zh/topics/nosql-databases" target="_blank" rel="noreferrer">https://www.ibm.com/cn-zh/topics/nosql-databases</a></li><li><a href="https://zhuanlan.zhihu.com/p/345342966" target="_blank" rel="noreferrer">https://zhuanlan.zhihu.com/p/345342966</a></li></ul>',12)])])}const _=a(d,[["render",n]]);export{S as __pageData,_ as default};
